// Tests for the sample host reference. The Philox engine is pinned
// bit-exact against vectors generated by the real hiprand/rocrand device
// headers compiled host-side (hipcc -x c++, ROCm 7.2, container
// gfx-rocm:7.2.4, 2026-11-12); the sampling math is checked against an
// independent long-double reference and the inner/outer noise equivalence.
#include "aiter_ref/sample.hpp"
#include "aiter_ref/rng.hpp"
#include "test_util.hpp"

#include <algorithm>
#include <cfloat>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <vector>

namespace {

using aiter_ref::Philox4x32_10;

struct UniVecs {
    std::uint64_t seed, subseq, offset;
    float u[8];  // two hiprand_uniform4 calls
};
struct SingVecs {
    std::uint64_t seed, subseq, offset;
    std::uint32_t w[10];  // ten hiprand() calls
};

// Generated by /tmp/gen_hiprand_vectors.cpp against ROCm 7.2 hiprand.
const UniVecs kUni[] = {
    {0ULL, 0ULL, 0ULL,
     {0.399046481f, 0.880520225f, 0.735712767f, 0.605481863f, 0.972241223f, 0.362091124f,
      0.693930924f, 0.037094079f}},
    {16045690984833335023ULL, 0ULL, 0ULL,
     {0.8529706f, 0.538245559f, 0.272714227f, 0.438561052f, 0.13663885f, 0.0228080563f,
      0.0969978198f, 0.697626173f}},
    {42ULL, 7ULL, 0ULL,
     {0.405981958f, 0.895814002f, 0.423809648f, 0.33379513f, 0.89791733f, 0.375234693f,
      0.561736643f, 0.174054638f}},
    {42ULL, 7ULL, 3ULL,
     {0.33379513f, 0.89791733f, 0.375234693f, 0.561736643f, 0.174054638f, 0.144241124f,
      0.937510192f, 0.340245068f}},
    {1311768467294899695ULL, 256ULL, 5ULL,
     {0.787791431f, 0.601641357f, 0.493387699f, 0.839449406f, 0.437285483f, 0.979793668f,
      0.483031273f, 0.496748418f}},
};
const SingVecs kSing[] = {
    {0ULL, 0ULL, 0ULL,
     {0x6627e8d5u, 0xe169c58du, 0xbc57ac4cu, 0x9b00dbd8u, 0xf8e4cca4u, 0x5cb200dbu,
      0xb1a574ebu, 0x097eff67u, 0x04faa329u, 0x51c732a6u}},
    {16045690984833335023ULL, 0ULL, 0ULL,
     {0xda5c487bu, 0x89ca764fu, 0x45d09968u, 0x70458958u, 0x22fac378u, 0x05d6bfb0u,
      0x18d4d95eu, 0xb297a08cu, 0x9f2086bdu, 0xf1680a31u}},
    {42ULL, 7ULL, 0ULL,
     {0x67ee6f2cu, 0xe55410ccu, 0x6c7eca35u, 0x557398d3u, 0xe5dde940u, 0x600f6196u,
      0x8fcdf8f1u, 0x2c8ed839u, 0x24ecfc6eu, 0xf000aacdu}},
    {42ULL, 7ULL, 3ULL,
     {0x557398d3u, 0xe5dde940u, 0x600f6196u, 0x8fcdf8f1u, 0x2c8ed839u, 0x24ecfc6eu,
      0xf000aacdu, 0x571a4cf0u, 0xd301a3d5u, 0x945bcadau}},
    {1311768467294899695ULL, 256ULL, 5ULL,
     {0xc9acb2ceu, 0x9a052b27u, 0x7e4ea7f1u, 0xd6e62858u, 0x6ff1f0f7u, 0xfad3c22au,
      0x7ba7efd6u, 0x7f2ae7b2u, 0x15a093beu, 0x926a8a57u}},
};

void philox_uniform4_bit_exact_vs_hiprand() {
    for (const auto& c : kUni) {
        Philox4x32_10 rng(c.seed, c.subseq, c.offset);
        const auto a = rng.uniform4();
        const auto b = rng.uniform4();
        for (int i = 0; i < 4; ++i) {
            CHECK(a[i] == c.u[i]);
            CHECK(b[i] == c.u[4 + i]);
        }
    }
}

void philox_next_bit_exact_vs_hiprand() {
    for (const auto& c : kSing) {
        Philox4x32_10 rng(c.seed, c.subseq, c.offset);
        for (int i = 0; i < 10; ++i) CHECK(rng.next() == c.w[i]);
    }
}

// offset=3 slides the window: the offset-3 stream starts at element 3 of the
// offset-0 stream (both in the uniform and raw domains — interleave works).
void philox_offset3_slides_window() {
    Philox4x32_10 a(42, 7, 0);
    std::vector<float> full;
    for (int i = 0; i < 4; ++i) {
        const auto v = a.uniform4();
        full.insert(full.end(), v.begin(), v.end());
    }
    Philox4x32_10 b(42, 7, 3);
    for (int call = 0; call < 2; ++call) {
        const auto v = b.uniform4();
        for (int i = 0; i < 4; ++i) CHECK(v[i] == full[3 + call * 4 + i]);
    }
}

void philox_uniform_transform_bounds() {
    CHECK(aiter_ref::philox_uniform(0u) == 2.3283064e-10f);
    // (float)0xffffffff rounds UP to 2^32, so the max value is exactly 1.0f —
    // the input the exponential clamp exists for.
    CHECK(aiter_ref::philox_uniform(0xFFFFFFFFu) == 1.0f);
}

void exponential_transform_clamp_quirk() {
    // u >= 1 - 2^-24 (incl. exactly 1.0f) -> log value pinned to 2^-24, and
    // c = -1 flips the sign: the noise is a tiny NEGATIVE number, so that
    // candidate can never win the race (pinned upstream behavior).
    CHECK(aiter_ref::exponential_transform(1.0f, 1.0f) == -5.9604645e-08f);
    CHECK(aiter_ref::exponential_transform(0.99999994f, 1.0f) == -5.9604645e-08f);
    CHECK(aiter_ref::exponential_transform(1.0f, 2.0f) == -2.9802322e-08f);
    // Regular path: -log(u)/lambd.
    CHECK_NEAR(aiter_ref::exponential_transform(0.5f, 1.0f), 0.69314718056f, 1e-7);
    CHECK_NEAR(aiter_ref::exponential_transform(0.5f, 2.0f), 0.34657359028f, 1e-7);
}

void greedy_sample_basics() {
    // Basic argmax; ties to the lower index.
    CHECK_EQ(aiter_ref::greedy_sample({1, 3, 2}, 1, 3)[0], 1);
    CHECK_EQ(aiter_ref::greedy_sample({5, 5, 1}, 1, 3)[0], 0);
    CHECK_EQ(aiter_ref::greedy_sample({-1, -7, -1}, 1, 3)[0], 0);
    // -FLT_MAX is a real value; only genuine -inf is the sentinel.
    CHECK_EQ(aiter_ref::greedy_sample({-FLT_MAX, -INFINITY, -FLT_MAX}, 1, 3)[0], 0);
    CHECK_EQ(aiter_ref::greedy_sample({-INFINITY, -INFINITY}, 1, 2)[0], 0);
    // NaN never wins; all-NaN row returns 0.
    CHECK_EQ(aiter_ref::greedy_sample({std::nanf(""), 2.0f}, 1, 2)[0], 1);
    CHECK_EQ(aiter_ref::greedy_sample({std::nanf(""), std::nanf("")}, 1, 2)[0], 0);
    // Multiple rows; an all-tie row picks the lowest index.
    const auto out = aiter_ref::greedy_sample({0, 9, 8, 4, 4, 4}, 2, 3);
    CHECK_EQ(out[0], 1);
    CHECK_EQ(out[1], 0);
}

void outer_exponential_forced_ties() {
    // Equal logits + equal noise: exact tie -> lower index.
    const std::vector<float> logits = {2, 2, 1, 1};
    const std::vector<float> temps = {1.0f};
    const std::vector<float> noise = {0.5f, 0.5f, 1.0f, 1.0f};
    CHECK_EQ(aiter_ref::random_sample_outer_exponential(logits, 1, 4, noise, temps)[0], 0);
    // Unequal noise breaks the tie by the race: smaller noise wins.
    const std::vector<float> n01 = {0.6f, 0.5f, 1.0f, 1.0f};
    CHECK_EQ(aiter_ref::random_sample_outer_exponential(logits, 1, 4, n01, temps)[0], 1);
    const std::vector<float> n10 = {0.5f, 0.6f, 1.0f, 1.0f};
    CHECK_EQ(aiter_ref::random_sample_outer_exponential(logits, 1, 4, n10, temps)[0], 0);
}

// Independent long-double reference: winner = argmax exp(x_i*inv_t) / u_i,
// ties to the lower index (the shared max/sum cancel out of the race).
std::int32_t ref_race_row(const std::vector<float>& x, float temp,
                          const std::vector<float>& noise, float eps) {
    const float t = temp > 1e-5f ? temp : 1e-5f;
    const long double inv_t = static_cast<long double>(1.0f / t);
    std::int32_t best = 0;
    long double best_v = -1.0L;
    for (std::size_t i = 0; i < x.size(); ++i) {
        const long double cand =
            std::exp(static_cast<long double>(x[i]) * inv_t) / (noise[i] + eps);
        if (cand > best_v) {
            best_v = cand;
            best = static_cast<std::int32_t>(i);
        }
    }
    return best;
}

void outer_exponential_matches_reference() {
    aiter_ref::Rng rng(0xC0FFEE);
    const std::size_t n = 128;
    for (int trial = 0; trial < 25; ++trial) {
        std::vector<float> logits(n);
        for (std::size_t i = 0; i < n; ++i)
            logits[i] = std::floor(rng.f32_sym() * 100.0f) / 100.0f;
        std::vector<float> noise(n);
        for (std::size_t i = 0; i < n; ++i) noise[i] = rng.f32_unit() + 0.01f;
        for (float temp : {0.7f, 1.0f, 3.5f}) {
            const std::vector<float> temps = {temp};
            const std::int32_t got =
                aiter_ref::random_sample_outer_exponential(logits, 1, n, noise, temps)[0];
            CHECK_EQ(got, ref_race_row(logits, temp, noise, 1e-10f));
        }
    }
}

// The core design claim: in-kernel sampling and noise-decoupled sampling
// pick the same token when the noise tensor comes from the same Philox
// schedule (eps is added at both ends upstream, pinned as-is; the 1e-10
// difference never flips a random race).
void random_and_outer_noise_paths_agree() {
    aiter_ref::Rng rng(0x5A17);
    for (int seed_case = 0; seed_case < 3; ++seed_case) {
        const std::uint64_t seed = 1000 + seed_case;
        const std::uint64_t offset = 8 * seed_case;
        const std::size_t m = 8, n = 300;
        std::vector<float> logits(m * n);
        for (float& v : logits) v = std::floor(rng.f32_sym() * 100.0f) / 100.0f;
        for (float lambd : {1.0f, 0.5f}) {
            std::vector<float> temps;
            for (std::size_t r = 0; r < m; ++r) temps.push_back(0.5f + 0.9f * r);
            const auto inner =
                aiter_ref::random_sample(logits, m, n, temps, lambd, seed, offset);
            const auto noise =
                aiter_ref::exponential_noise(m, n, lambd, seed, offset);
            const auto outer =
                aiter_ref::random_sample_outer_exponential(logits, m, n, noise, temps);
            CHECK_VEC_EQ(inner, outer);
        }
    }
}

void mixed_dispatches_per_row() {
    aiter_ref::Rng rng(0xD15E);
    const std::size_t m = 4, n = 64;
    std::vector<float> logits(m * n);
    for (float& v : logits) v = std::floor(rng.f32_sym() * 100.0f) / 100.0f;
    std::vector<float> temps = {0.0f, 0.8f, 0.0f, 1.7f};
    const auto mixed = aiter_ref::mixed_sample(logits, m, n, temps, 1.0f, 7, 0);
    const auto greedy = aiter_ref::greedy_sample(logits, m, n);
    const auto sampled = aiter_ref::random_sample(logits, m, n, temps, 1.0f, 7, 0);
    CHECK_EQ(mixed[0], greedy[0]);
    CHECK_EQ(mixed[1], sampled[1]);
    CHECK_EQ(mixed[2], greedy[2]);
    CHECK_EQ(mixed[3], sampled[3]);
    // Outer variant: temp-0 rows greedy, others == the outer sampler.
    const auto noise = aiter_ref::exponential_noise(m, n, 1.0f, 7, 0);
    const auto mixed_o = aiter_ref::mixed_sample_outer_exponential(logits, m, n, noise, temps);
    const auto outer_o = aiter_ref::random_sample_outer_exponential(logits, m, n, noise, temps);
    CHECK_EQ(mixed_o[0], greedy[0]);
    CHECK_EQ(mixed_o[1], outer_o[1]);
    CHECK_EQ(mixed_o[3], outer_o[3]);
}

void temperature_clamped_at_1e_minus5() {
    aiter_ref::Rng rng(0x7E5D);
    const std::size_t n = 100;
    std::vector<float> logits(n);
    for (float& v : logits) v = std::floor(rng.f32_sym() * 100.0f) / 100.0f;
    const std::vector<float> t_tiny = {1e-9f}, t_clamp = {1e-5f};
    CHECK_VEC_EQ(aiter_ref::random_sample(logits, 1, n, t_tiny, 1.0f, 3, 0),
                 aiter_ref::random_sample(logits, 1, n, t_clamp, 1.0f, 3, 0));
    // Near-argmax at the clamp: a dominant logit wins with overwhelming
    // probability under Exp(1) noise.
    std::vector<float> dominant(n, 0.0f);
    dominant[42] = 30.0f;
    CHECK_EQ(aiter_ref::random_sample(dominant, 1, n, t_tiny, 1.0f, 5, 0)[0], 42);
}

void all_nan_row_returns_zero() {
    const std::size_t n = 8;
    std::vector<float> logits(n, std::nanf(""));
    const std::vector<float> temps = {1.0f};
    const std::vector<float> noise(n, 1.0f);
    CHECK_EQ(aiter_ref::random_sample_outer_exponential(logits, 1, n, noise, temps)[0], 0);
    const auto inner = aiter_ref::random_sample(logits, 1, n, temps, 1.0f, 1, 0);
    CHECK_EQ(inner[0], 0);
}

void counter_offset_contract() {
    // Mirrors aiter/ops/sample.py _philox_seed_offset.
    CHECK_EQ(aiter_ref::philox_counter_offset(1, 1), 4);
    CHECK_EQ(aiter_ref::philox_counter_offset(4096, 1), 4);
    CHECK_EQ(aiter_ref::philox_counter_offset(4097, 1), 8);
    CHECK_EQ(aiter_ref::philox_counter_offset(1024 * 8 * 4, 8), 4);
    CHECK_EQ(aiter_ref::philox_counter_offset(1024 * 8 * 4 + 1, 8), 8);
}

void high_temperature_spreads_winners() {
    // temp=50 flattens the softmax; the exponential race should not collapse
    // onto one token across rows (each row has its own Philox subsequence).
    const std::size_t m = 200, n = 64;
    std::vector<float> logits(m * n, 0.0f);
    const std::vector<float> temps(m, 50.0f);
    const auto out = aiter_ref::random_sample(logits, m, n, temps, 1.0f, 99, 0);
    std::vector<char> seen(n, 0);
    int distinct = 0;
    for (std::int32_t v : out) {
        if (!seen[v]) {
            seen[v] = 1;
            ++distinct;
        }
    }
    CHECK(distinct >= 10);
}

}  // namespace

int main() {
    RUN_TEST(philox_uniform4_bit_exact_vs_hiprand);
    RUN_TEST(philox_next_bit_exact_vs_hiprand);
    RUN_TEST(philox_offset3_slides_window);
    RUN_TEST(philox_uniform_transform_bounds);
    RUN_TEST(exponential_transform_clamp_quirk);
    RUN_TEST(greedy_sample_basics);
    RUN_TEST(outer_exponential_forced_ties);
    RUN_TEST(outer_exponential_matches_reference);
    RUN_TEST(random_and_outer_noise_paths_agree);
    RUN_TEST(mixed_dispatches_per_row);
    RUN_TEST(temperature_clamped_at_1e_minus5);
    RUN_TEST(all_nan_row_returns_zero);
    RUN_TEST(counter_offset_contract);
    RUN_TEST(high_temperature_spreads_winners);
    return finish();
}
